import { createContext } from 'react';

export const controlGroupSizes = ['XSmall', 'Small', 'Medium'] as const;
export type TControlGroupSize = (typeof controlGroupSizes)[number];

export type TControlGroupContext = {
  size: TControlGroupSize;
  placement: 'Start' | 'End';
  isDisabled: boolean;
};

export const CheckboxGroupContext = createContext<TControlGroupContext | null>(null);

export const ToggleGroupContext = createContext<
  | (TControlGroupContext & {
      value: string | undefined;
      onValueChange: (value: string) => void;
    })
  | null
>(null);

export const ChipGroupContext = createContext<{
  size: 'Small' | 'Medium';
  isDisabled: boolean;
} | null>(null);
